  for(let b of bricks){
    if(!b.alive)continue;
    if(bx>b.x&&bx<b.x+b.w&&by>b.y&&by<b.y+b.h){
      if(pierce<=0)bdy=-bdy;
      if(--b.hp<=0){
        b.alive=false;combo++;score+=100*combo*scoreMult;
        spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,20);
        if(fireball)explodeBricks(b.x+b.w/2,b.y+b.h/2,80);
      }else{if(!comboLock)combo=0;spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,8)}
      document.getElementById('scoreVal').textContent=score;
