    if(eb.y<=ballR)eb.dy=-eb.dy;
    if(eb.y>H){extraBalls.splice(i,1);continue}
    if(eb.y+ballR>=py&&eb.y+ballR<=py+paddleH+4&&eb.x>px&&eb.x<px+paddleW){
      let hit=(eb.x-px)/paddleW;
