  // Level clear
  if(bricks.every(b=>!b.alive)){showUpgradeScreen()}
  // Particles
  for(let i=particles.length-1;i>=0;i--){
    let p=particles[i];p.x+=p.vx;p.y+=p.vy;p.life-=0.025;
    if(p.life<=0)particles.splice(i,1);
