  o.innerHTML=`<h1>${lives>0?'VICTORY!':'GAME OVER'}</h1><p>Score: ${score}</p><p>Level Reached: ${level}</p>${runInfo}<button onclick="startGame()">PLAY AGAIN</button>`;
}

