    if(magnetHeld){magnetHeld=false;let spd=4+level*0.4;bdx=spd*(Math.random()-.5)*2;bdy=-spd;return}
    if(!running&&!upgrading)startGame();
  }
  if(e.key==='ArrowUp'&&magnetHeld){magnetHeld=false;let spd=4+level*0.4;bdx=spd*(Math.random()-.5)*2;bdy=-spd}
});

