// Vampire Survivors: score-triggered upgrades
let upgradeCount=0;
function getNextThreshold(){return 500+upgradeCount*700+upgradeCount*upgradeCount*100}
let nextUpgradeScore=getNextThreshold();

const UPGRADES=[
  {id:'life',icon:'\u2764',name:'Extra Life',desc:'+1 Life',rarity:'common',apply:()=>{lives++;document.getElementById('livesVal').textContent=lives}},
  {id:'paddle_w',icon:'\u2194',name:'Wide Paddle',desc:'+30 paddle width',rarity:'common',apply:()=>{paddleW+=30}},
  {id:'big_ball',icon:'\u25CF',name:'Big Ball',desc:'+3 ball radius',rarity:'common',apply:()=>{ballR+=3}},
  {id:'slow',icon:'\u23F1',name:'Slow Motion',desc:'-15% ball speed',rarity:'common',apply:()=>{let s=Math.sqrt(bdx*bdx+bdy*bdy);let ns=s*0.85;let r=ns/s;bdx*=r;bdy*=r}},
  {id:'score_x',icon:'\u00D72',name:'Score Boost',desc:'2x score multiplier',rarity:'rare',apply:()=>{scoreMult*=2}},
  {id:'magnet',icon:'\u{1F9F2}',name:'Magnet Paddle',desc:'Ball sticks on catch',rarity:'rare',apply:()=>{magnet=true}},
  {id:'pierce',icon:'\u2694',name:'Pierce Shot',desc:'Ball pierces bricks',rarity:'epic',apply:()=>{pierce++}},
  {id:'multi',icon:'\u2726',name:'Multi Ball',desc:'+1 extra ball',rarity:'epic',apply:()=>{spawnExtraBall()}},
  {id:'fireball',icon:'\u{1F525}',name:'Fireball',desc:'Explosive on impact',rarity:'legendary',apply:()=>{fireball=true}},
  {id:'shield',icon:'\u{1F6E1}',name:'Shield',desc:'One-time bottom save',rarity:'rare',apply:()=>{shieldCount++}},
  {id:'combo_keep',icon:'\u{1F517}',name:'Combo Lock',desc:'Combo never resets',rarity:'legendary',apply:()=>{comboLock=true}},
  {id:'laser',icon:'\u{1F4A1}',name:'Laser Paddle',desc:'Shoot lasers on click',rarity:'epic',apply:()=>{laserMode=true}},
];
let scoreMult=1,magnet=false,pierce=0,fireball=false,shieldCount=0,comboLock=false,laserMode=false;
let extraBalls=[],lasers=[];

function updateXPBar(){
  let prev=upgradeCount>0?(500+(upgradeCount-1)*700+(upgradeCount-1)*(upgradeCount-1)*100):0;
  let range=nextUpgradeScore-prev;
  let prog=Math.min(1,(score-prev)/range);
  document.getElementById('xp-bar').style.width=(prog*100)+'%';
  document.getElementById('xp-label').textContent='Next upgrade: '+nextUpgradeScore+' ('+Math.floor(prog*100)+'%)';
}

function flashLevelUp(){
  let el=document.getElementById('levelup-flash');
  el.style.opacity='1';
  setTimeout(()=>{el.style.opacity='0'},800);
}

function initBricks(){
  bricks=[];
  let extraRows=Math.min(level-1,3);
  for(let r=0;r<rows+extraRows;r++)for(let c=0;c<cols;c++){
    let x=c*(bw+gap)+35,y=r*(bh+gap)+topOff;
    let hp=1;
    if(r<2)hp=2;
    if(level>3&&r<1)hp=3;
    if(level>6&&r===0)hp=4;
    bricks.push({x,y,w:bw,h:bh,color:colors[r%7],alive:true,hp,maxHp:hp});
  }
}

function resetBall(){bx=W/2;by=H-50;let spd=4+level*0.4;bdx=spd*(Math.random()>.5?1:-1);bdy=-spd}

function spawnExtraBall(){
  let spd=Math.sqrt(bdx*bdx+bdy*bdy);
  extraBalls.push({x:bx,y:by,dx:spd*(Math.random()-.5)*2,dy:-spd,trail:[]});
}

function spawnParticles(x,y,color,n=15){
  for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*6,vy:(Math.random()-.5)*6,life:1,color});
}

function explodeBricks(bx2,by2,radius){
  for(let b of bricks){
    if(!b.alive)continue;
    let cx=b.x+b.w/2,cy=b.y+b.h/2;
    let dist=Math.sqrt((cx-bx2)**2+(cy-by2)**2);
    if(dist<radius){
      b.hp-=2;
      if(b.hp<=0){b.alive=false;combo++;score+=100*combo*scoreMult;spawnParticles(cx,cy,b.color,15)}
    }
  }
}

function checkUpgradeThreshold(){
  if(score>=nextUpgradeScore){
    flashLevelUp();
    showUpgradeScreen();
  }
  updateXPBar();
}

function showUpgradeScreen(){
  upgrading=true;running=false;
  let pool=[...UPGRADES];
  let picks=[];
  let tries=0;
  while(picks.length<3&&tries<50){
    tries++;
    let idx=Math.floor(Math.random()*pool.length);
    let u=pool[idx];
    let w=u.rarity==='common'?40:u.rarity==='rare'?25:u.rarity==='epic'?10:3;
    if(Math.random()*100<w&&!picks.find(p=>p.id===u.id)){picks.push(u)}
  }
  while(picks.length<3)picks.push(UPGRADES[Math.floor(Math.random()*UPGRADES.length)]);
  let html='';
  picks.forEach((u,i)=>{
    html+=`<div class="upgrade-card" onclick="pickUpgrade(${i})"><div class="icon">${u.icon}</div><div class="name">${u.name}</div><div class="desc">${u.desc}</div><span class="rarity rarity-${u.rarity}">${u.rarity.toUpperCase()}</span></div>`;
  });
  document.getElementById('upgrade-cards').innerHTML=html;
  document.getElementById('upgrade-sub').textContent='Upgrade #'+(upgradeCount+1)+' — Pick a power:';
  document.getElementById('upgrade-overlay').style.display='flex';
  window._upgradePicks=picks;
}

window.pickUpgrade=function(i){
  let u=window._upgradePicks[i];
  u.apply();
  buffs.push({name:u.name,rarity:u.rarity});
  updateBuffDisplay();
  document.getElementById('upgrade-overlay').style.display='none';
  upgrading=false;running=true;
  upgradeCount++;
  nextUpgradeScore=getNextThreshold();
  updateXPBar();
};

function updateBuffDisplay(){
  let el=document.getElementById('buffs');
  el.innerHTML=buffs.map(b=>`<span class="buff-tag" style="border-color:${b.rarity==='legendary'?'#ff0':b.rarity==='epic'?'#f0f':b.rarity==='rare'?'#08f':'#0f0'}">${b.name}</span>`).join('');
}

function startGame(){
  score=0;lives=3;level=1;combo=0;gameOver=false;running=true;upgrading=false;
  paddleW=120;ballR=8;scoreMult=1;magnet=false;pierce=0;fireball=false;shieldCount=0;comboLock=false;laserMode=false;
  extraBalls=[];lasers=[];buffs=[];upgradeCount=0;nextUpgradeScore=getNextThreshold();
  document.getElementById('overlay').style.display='none';
  document.getElementById('upgrade-overlay').style.display='none';
  updateBuffDisplay();updateXPBar();
  initBricks();resetBall();
}

function update(){
  if(!running||gameOver||upgrading)return;
  if(mouseX>0)px=Math.max(0,Math.min(W-paddleW,mouseX-paddleW/2));
  bx+=bdx;by+=bdy;
  if(bx<=ballR||bx>=W-ballR)bdx=-bdx;
  if(by<=ballR)bdy=-bdy;
  if(by>H){
    if(shieldCount>0){shieldCount--;by=H-10;bdy=-Math.abs(bdy);spawnParticles(bx,H,'#0ff',30);return}
    lives--;document.getElementById('livesVal').textContent=lives;
    if(!comboLock){combo=0;document.getElementById('comboVal').textContent=0}
    if(lives<=0){gameOver=true;showOverlay()}else resetBall();
