  // Higher difficulty: some bricks are tougher
  for(let c=0;c<cols;c++){
    let x=c*(bw+gap)+35,y=-bh-5;
    let hp=1;
    let r=Math.random();
    if(difficultyLevel>=3&&r<0.2)hp=Math.min(maxHp,2);
    if(difficultyLevel>=5&&r<0.15)hp=Math.min(maxHp,3);
    if(difficultyLevel>=8&&r<0.1)hp=Math.min(maxHp,4);
    if(difficultyLevel>=12&&r<0.05)hp=Math.min(maxHp,5);
    // Special brick types at high difficulty
    let type='normal';
    if(difficultyLevel>=6&&Math.random()<0.08)type='armored'; // takes 2x hits
    if(difficultyLevel>=10&&Math.random()<0.05)type='regen'; // slowly regenerates
    if(type==='armored')hp=Math.ceil(hp*1.5);
    if(type==='regen')hp=Math.ceil(hp*1.3);
    bricks.push({x,y,w:bw,h:bh,color:rowColor,alive:true,hp,maxHp:hp,type});
  }
  wave++;
  document.getElementById('levelVal').textContent=wave;
}

function resetBall(){bx=W/2;by=H-50;let spd=4+difficultyLevel*0.15;bdx=spd*(Math.random()>.5?1:-1);bdy=-spd}

function spawnExtraBall(){
  let spd=Math.sqrt(bdx*bdx+bdy*bdy);
  extraBalls.push({x:bx,y:by,dx:spd*(Math.random()-.5)*2,dy:-spd,trail:[]});
}

function spawnParticles(x,y,color,n=15){
  for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*6,vy:(Math.random()-.5)*6,life:1,color});
}

function explodeBricks(bx2,by2,radius){
  for(let b of bricks){
    if(!b.alive)continue;
    let cx=b.x+b.w/2,cy=b.y+b.h/2;
    let dist=Math.sqrt((cx-bx2)**2+(cy-by2)**2);
    if(dist<radius){
      b.hp-=2;
      if(b.hp<=0){b.alive=false;combo++;score+=100*combo*scoreMult;spawnParticles(cx,cy,b.color,15)}
    }
  }
}

function checkUpgradeThreshold(){
  if(score>=nextUpgradeScore){
    flashLevelUp();
    showUpgradeScreen();
  }
  updateXPBar();
}

function showUpgradeScreen(){
  upgrading=true;running=false;
  let pool=[...UPGRADES];
  let picks=[];
  let tries=0;
  while(picks.length<3&&tries<50){
    tries++;
    let idx=Math.floor(Math.random()*pool.length);
    let u=pool[idx];
    let w=u.rarity==='common'?40:u.rarity==='rare'?25:u.rarity==='epic'?10:3;
    if(Math.random()*100<w&&!picks.find(p=>p.id===u.id)){picks.push(u)}
  }
  while(picks.length<3)picks.push(UPGRADES[Math.floor(Math.random()*UPGRADES.length)]);
  let html='';
  picks.forEach((u,i)=>{
    html+=`<div class="upgrade-card" onclick="pickUpgrade(${i})"><div class="icon">${u.icon}</div><div class="name">${u.name}</div><div class="desc">${u.desc}</div><span class="rarity rarity-${u.rarity}">${u.rarity.toUpperCase()}</span></div>`;
  });
  document.getElementById('upgrade-cards').innerHTML=html;
  document.getElementById('upgrade-sub').textContent='Upgrade #'+(upgradeCount+1)+' — Pick a power:';
  document.getElementById('upgrade-overlay').style.display='flex';
  window._upgradePicks=picks;
}

window.pickUpgrade=function(i){
  let u=window._upgradePicks[i];
  u.apply();
  buffs.push({name:u.name,rarity:u.rarity});
  updateBuffDisplay();
  document.getElementById('upgrade-overlay').style.display='none';
  upgrading=false;running=true;
  upgradeCount++;
  nextUpgradeScore=getNextThreshold();
  updateXPBar();
};
function updateBuffDisplay(){
  let el=document.getElementById('buffs');
  el.innerHTML=buffs.map(b=>`<span class="buff-tag" style="border-color:${b.rarity==='legendary'?'#ff0':b.rarity==='epic'?'#f0f':b.rarity==='rare'?'#08f':'#0f0'}">${b.name}</span>`).join('');
}

function startGame(){
  score=0;lives=3;wave=1;combo=0;gameOver=false;running=true;upgrading=false;
  paddleW=120;ballR=8;scoreMult=1;magnet=false;pierce=0;fireball=false;shieldCount=0;comboLock=false;laserMode=false;
  extraBalls=[];lasers=[];buffs=[];upgradeCount=0;nextUpgradeScore=getNextThreshold();
  brickSpeed=0.15;spawnTimer=0;spawnInterval=180;gameTime=0;difficultyLevel=1;
  bricks=[];
  document.getElementById('overlay').style.display='none';
  document.getElementById('upgrade-overlay').style.display='none';
  updateBuffDisplay();updateXPBar();
  // Spawn initial rows
  for(let i=0;i<5;i++){
    let cols=10,bw=65,bh=20,gap=8;
    for(let c=0;c<cols;c++){
      let x=c*(bw+gap)+35,y=i*(bh+gap)+40;
      let hp=i<2?2:1;
      bricks.push({x,y,w:bw,h:bh,color:colors[i%7],alive:true,hp,maxHp:hp,type:'normal'});
    }
  }
  wave=5;document.getElementById('levelVal').textContent=wave;
  resetBall();
}

function update(){
  if(!running||gameOver||upgrading)return;
  gameTime++;
  // Difficulty scales with time
  difficultyLevel=1+Math.floor(gameTime/600); // every ~10 seconds
  // Speed up brick spawning over time
  spawnInterval=Math.max(60,180-difficultyLevel*8);
  brickSpeed=0.15+difficultyLevel*0.03;
  // Spawn new rows
  spawnTimer++;
  if(spawnTimer>=spawnInterval){spawnTimer=0;spawnRow()}
  // Move bricks down
  for(let i=bricks.length-1;i>=0;i--){
    let b=bricks[i];
    if(!b.alive){bricks.splice(i,1);continue}
    b.y+=brickSpeed;
    // Regen bricks slowly heal
    if(b.type==='regen'&&b.hp<b.maxHp&&gameTime%120===0)b.hp=Math.min(b.maxHp,b.hp+1);
    // Brick reached bottom = lose life
    if(b.y+b.h>=py){
      b.alive=false;
      spawnParticles(b.x+b.w/2,b.y+b.h/2,'#f00',20);
      if(shieldCount>0){shieldCount--;continue}
      lives--;document.getElementById('livesVal').textContent=lives;
      if(!comboLock){combo=0;document.getElementById('comboVal').textContent=0}
      if(lives<=0){gameOver=true;showOverlay()}
    }
  }
  // Paddle
  if(mouseX>0)px=Math.max(0,Math.min(W-paddleW,mouseX-paddleW/2));
  // Main ball
  bx+=bdx;by+=bdy;
  if(bx<=ballR||bx>=W-ballR)bdx=-bdx;
  if(by<=ballR)bdy=-bdy;
  if(by>H){
    if(shieldCount>0){shieldCount--;by=H-10;bdy=-Math.abs(bdy);spawnParticles(bx,H,'#0ff',30);return}
    lives--;document.getElementById('livesVal').textContent=lives;
    if(!comboLock){combo=0;document.getElementById('comboVal').textContent=0}
    if(lives<=0){gameOver=true;showOverlay()}else resetBall();
  }
  if(by+ballR>=py&&by+ballR<=py+paddleH+4&&bx>px&&bx<px+paddleW){
    if(magnet){by=py-ballR;bdx=0;bdy=0;magnetHeld=true;return}
    let hit=(bx-px)/paddleW;
    let angle=hit*Math.PI*0.66-Math.PI*0.33;
    let spd=Math.sqrt(bdx*bdx+bdy*bdy);
    bdx=spd*Math.sin(angle);bdy=-spd*Math.cos(angle);
    spawnParticles(bx,py,'#0ff',8);
  }
  // Ball-brick collision
  for(let b of bricks){
    if(!b.alive)continue;
    if(bx>b.x&&bx<b.x+b.w&&by>b.y&&by<b.y+b.h){
      if(pierce<=0)bdy=-bdy;
      if(--b.hp<=0){
        b.alive=false;combo++;score+=100*combo*scoreMult;
        spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,20);
        if(fireball)explodeBricks(b.x+b.w/2,b.y+b.h/2,80);
      }else{if(!comboLock)combo=0;spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,8)}
      document.getElementById('scoreVal').textContent=score;
      document.getElementById('comboVal').textContent=combo;
      checkUpgradeThreshold();
      if(pierce<=0)break;
    }
  }
  // Extra balls
  for(let i=extraBalls.length-1;i>=0;i--){
    let eb=extraBalls[i];
    eb.x+=eb.dx;eb.y+=eb.dy;
    if(eb.x<=ballR||eb.x>=W-ballR)eb.dx=-eb.dx;
    if(eb.y<=ballR)eb.dy=-eb.dy;
    if(eb.y>H){extraBalls.splice(i,1);continue}
    if(eb.y+ballR>=py&&eb.y+ballR<=py+paddleH+4&&eb.x>px&&eb.x<px+paddleW){
      let hit=(eb.x-px)/paddleW;
      let angle=hit*Math.PI*0.66-Math.PI*0.33;
      let spd=Math.sqrt(eb.dx*eb.dx+eb.dy*eb.dy);
      eb.dx=spd*Math.sin(angle);eb.dy=-spd*Math.cos(angle);
    }
    for(let b of bricks){
      if(!b.alive)continue;
      if(eb.x>b.x&&eb.x<b.x+b.w&&eb.y>b.y&&eb.y<b.y+b.h){
        eb.dy=-eb.dy;
        if(--b.hp<=0){b.alive=false;combo++;score+=100*combo*scoreMult;spawnParticles(b.x+b.w/2,b.y+b.h/2,b.color,20);if(fireball)explodeBricks(b.x+b.w/2,b.y+b.h/2,80)}
        document.getElementById('scoreVal').textContent=score;
        document.getElementById('comboVal').textContent=combo;
        checkUpgradeThreshold();
        break;
      }
    }
  }
  // Lasers
  for(let i=lasers.length-1;i>=0;i--){
    let l=lasers[i];l.y-=8;
    if(l.y<0){lasers.splice(i,1);continue}
    for(let b of bricks){
      if(!b.alive)continue;
      if(l.x>b.x&&l.x<b.x+b.w&&l.y>b.y&&l.y<b.y+b.h){
        if(--b.hp<=0){b.alive=false;combo++;score+=100*combo*scoreMult;spawnParticles(b.x+b.w/2,b.y+b.h/2,'#f80',15)}
        document.getElementById('scoreVal').textContent=score;
        document.getElementById('comboVal').textContent=combo;
        checkUpgradeThreshold();
        lasers.splice(i,1);break;
      }
    }
  }
  // Particles
  for(let i=particles.length-1;i>=0;i--){
    let p=particles[i];p.x+=p.vx;p.y+=p.vy;p.life-=0.025;
    if(p.life<=0)particles.splice(i,1);
  }
}

function draw(){
  X.fillStyle="#0a0a0f";X.fillRect(0,0,W,H);
  // Stars
  stars.forEach(s=>{X.globalAlpha=Math.abs(s.a)*0.6;X.fillStyle="#fff";X.beginPath();X.arc(s.x,s.y,s.r,0,Math.PI*2);X.fill()});
  X.globalAlpha=1;
  // Danger zone indicator at bottom
  let dangerY=py-20;
  X.strokeStyle='rgba(255,0,0,0.15)';X.lineWidth=1;X.setLineDash([5,5]);
  X.beginPath();X.moveTo(0,dangerY);X.lineTo(W,dangerY);X.stroke();
  X.setLineDash([]);
  // Bricks
  for(let b of bricks){if(!b.alive)continue;
    X.shadowColor=b.color;X.shadowBlur=15;
    X.fillStyle=b.color;X.fillRect(b.x,b.y,b.w,b.h);
    X.shadowBlur=0;
    // HP bar
    if(b.hp<b.maxHp){X.fillStyle='rgba(0,0,0,0.4)';X.fillRect(b.x,b.y,b.w*(1-b.hp/b.maxHp),b.h)}
    // Type indicator
    if(b.type==='armored'){X.strokeStyle='#fff';X.lineWidth=2;X.strokeRect(b.x+1,b.y+1,b.w-2,b.h-2)}
    if(b.type==='regen'){X.fillStyle='rgba(0,255,0,0.3)';X.fillRect(b.x,b.y,b.w,b.h)}
    X.strokeStyle="rgba(255,255,255,0.3)";X.lineWidth=1;X.strokeRect(b.x+0.5,b.y+0.5,b.w-1,b.h-1)}
  // Ball trail
  ball.trail.forEach(t=>{X.globalAlpha=t.a*0.4;X.fillStyle=fireball?'#f80':'#0ff';X.beginPath();X.arc(t.x,t.y,ballR*0.6,0,Math.PI*2);X.fill()});
  X.globalAlpha=1;
  // Main ball
  X.shadowColor=fireball?'#f80':'#0ff';X.shadowBlur=20;
  X.fillStyle=fireball?'#f80':'#0ff';X.beginPath();X.arc(bx,by,ballR,0,Math.PI*2);X.fill();
  X.shadowBlur=0;
  // Extra balls
  extraBalls.forEach(eb=>{
    eb.trail.forEach(t=>{X.globalAlpha=t.a*0.3;X.fillStyle='#f0f';X.beginPath();X.arc(t.x,t.y,ballR*0.5,0,Math.PI*2);X.fill()});
    X.globalAlpha=1;X.shadowColor='#f0f';X.shadowBlur=15;X.fillStyle='#f0f';X.beginPath();X.arc(eb.x,eb.y,ballR,0,Math.PI*2);X.fill();X.shadowBlur=0;
  });
  // Lasers
  lasers.forEach(l=>{X.shadowColor='#f80';X.shadowBlur=10;X.fillStyle='#f80';X.fillRect(l.x-2,l.y,4,12);X.shadowBlur=0});
  // Paddle
  X.shadowColor='#0ff';X.shadowBlur=10;
  let grd=X.createLinearGradient(px,py,px+paddleW,py);
  grd.addColorStop(0,'#0ff');grd.addColorStop(.5,'#f0f');grd.addColorStop(1,'#0ff');
  X.fillStyle=grd;X.shadowBlur=15;X.fillRect(px,py,paddleW,paddleH);
  X.shadowBlur=0;
  // Shield
  if(shieldCount>0){
    X.strokeStyle='#ff0';X.shadowColor='#ff0';X.shadowBlur=10;X.lineWidth=2;
    X.setLineDash([10,5]);X.beginPath();X.moveTo(0,H-5);X.lineTo(W,H-5);X.stroke();
    X.setLineDash([]);X.shadowBlur=0;
  }
  // Particles
  particles.forEach(p=>{X.globalAlpha=p.life;X.fillStyle=p.color;X.shadowColor=p.color;X.shadowBlur=10;X.fillRect(p.x-2,p.y-2,4,4)});
  X.globalAlpha=1;X.shadowBlur=0;
  // Difficulty indicator
  X.fillStyle='rgba(0,255,255,0.5)';X.font='12px "Courier New"';
  X.fillText('Difficulty: '+difficultyLevel+' | Brick Speed: '+brickSpeed.toFixed(2)+' | Spawn: '+(spawnInterval/60).toFixed(1)+'s',10,H-10);
}

function showOverlay(){
  let o=document.getElementById('overlay');o.style.display='flex';
  let runInfo=buffs.length>0?`<p style="color:#f0f">Upgrades: ${buffs.map(b=>b.name).join(', ')}</p>`:'';
  o.innerHTML=`<h1>GAME OVER</h1><p>Score: ${score}</p><p>Waves Survived: ${wave}</p><p>Max Difficulty: ${difficultyLevel}</p><p>Upgrades Collected: ${upgradeCount}</p>${runInfo}<button onclick="startGame()">PLAY AGAIN</button>`;
}

let mouseX=-1,magnetHeld=false;
C.addEventListener('mousemove',e=>{mouseX=e.clientX-C.getBoundingClientRect().left});
C.addEventListener('click',()=>{
  if(laserMode&&running){lasers.push({x:px+paddleW/2,y:py});lasers.push({x:px+10,y:py});lasers.push({x:px+paddleW-10,y:py})}
});
document.addEventListener('keydown',e=>{
  if(e.key==='ArrowLeft')px=Math.max(0,px-25);
  if(e.key==='ArrowRight')px=Math.min(W-paddleW,px+25);
  if(e.key===' '){
    if(magnetHeld){magnetHeld=false;let spd=4+difficultyLevel*0.15;bdx=spd*(Math.random()-.5)*2;bdy=-spd;return}
    if(!running&&!upgrading)startGame();
  }
  if(e.key==='ArrowUp'&&magnetHeld){magnetHeld=false;let spd=4+difficultyLevel*0.15;bdx=spd*(Math.random()-.5)*2;bdy=-spd}
});

let ball={trail:[]};
function loop(){
  if(running){
    ball.trail.push({x:bx,y:by,a:1});
    if(ball.trail.length>8)ball.trail.shift();
    ball.trail.forEach(t=>t.a*=0.92);
    extraBalls.forEach(eb=>{eb.trail.push({x:eb.x,y:eb.y,a:1});if(eb.trail.length>6)eb.trail.shift();eb.trail.forEach(t=>t.a*=0.9)});
  }
  update();draw();
  requestAnimationFrame(loop);
}
loop();
</script></body></html>
